        uint256 updatedAt;
    }

    function isDeposited(
        bytes32 txHash,
        uint32 txout
    ) external view returns (bool);

    function deposit(
        bytes32 txHash,
        uint32 txout,
        address target,
        uint256 amount,
        uint256 tax
    ) external;

    function withdraw(
        string calldata receiver,
        uint16 maxTxPrice
    ) external payable;

    function replaceByFee(uint256 id, uint16 maxTxPrice) external;

    function cancel1(uint256 id) external;

    function refund(uint256 id) external;

    function cancel2(uint256 id) external;

    function paid(
        uint256 id,
        bytes32 txHash,
        uint32 txout,
        uint256 received
    ) external;
}
