{"compiler":{"version":"0.8.27+commit.40a35a09"},"language":"Solidity","output":{"abi":[{"inputs":[{"internalType":"uint256","name":"count","type":"uint256"},{"internalType":"bool","name":"checkSender","type":"bool"}],"stateMutability":"nonpayable","type":"constructor"},{"inputs":[],"name":"RateLimitExceeded","type":"error"},{"inputs":[],"name":"RequestTooFrequent","type":"error"},{"inputs":[],"name":"TooManyRequest","type":"error"},{"inputs":[],"name":"REQUEST_PER_BLOCK","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"}],"devdoc":{"kind":"dev","methods":{},"version":1},"userdoc":{"kind":"user","methods":{},"notice":"The rate limiter for consensus request","version":1}},"settings":{"compilationTarget":{"contracts/library/utils/RateLimiter.sol":"RateLimiter"},"evmVersion":"cancun","libraries":{},"metadata":{"bytecodeHash":"none","useLiteralContent":true},"optimizer":{"enabled":true,"runs":800},"remappings":[]},"sources":{"contracts/library/utils/RateLimiter.sol":{"content":"// SPDX-License-Identifier: Apache 2.0
pragma solidity ^0.8.24;

/**
 * The rate limiter for consensus request
 */
contract RateLimiter {
    error TooManyRequest();
    error RequestTooFrequent();
    error RateLimitExceeded();

    uint256 public immutable REQUEST_PER_BLOCK;
    bool internal immutable CHECK_SENDER;

    constructor(uint256 count, bool checkSender) {
        REQUEST_PER_BLOCK = count;
        CHECK_SENDER = checkSender;
    }

    struct RateLimit {
        uint256 height;
        uint256 count;
        mapping(address caller => uint256 height) callers;
    }

    RateLimit internal rateLimit;

    modifier RateLimiting() {
        _checkLimiting(msg.sender, 1);
        _;
    }

    modifier RateLimiting2(address target, uint256 count) {
        _checkLimiting(target, count);
        _;
    }

    function _checkLimiting(address target, uint256 count) internal {
        if (CHECK_SENDER) {
            require(
                rateLimit.callers[target] != block.number,
                TooManyRequest()
            );
            rateLimit.callers[target] = block.number;
        }

        if (count == 0) {
            return;
        }

        if (block.number == rateLimit.height) {
            rateLimit.count += count;
        } else {
            rateLimit.height = block.number;
            rateLimit.count = count;
        }
        require(rateLimit.count <= REQUEST_PER_BLOCK, RateLimitExceeded());
    }
}
","keccak256":"0x12ee0a7b090a308459cfec94a943430c5a6131974b91d787655faecf303bd47c","license":"Apache 2.0"}},"version":1}

